using System.Text.Json;
using RansomFree.Client;
using RansomFree.Contracts;
var root=Path.Combine("D:\\Codex\\RansomFree\\tests","trust-cache-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var checks=new List<string>();void Check(bool value,string label){if(!value)throw new Exception(label);checks.Add("PASS: "+label);Console.WriteLine(checks[^1]);}
void Reject(Action action,string label){var rejected=false;try{action();}catch(Exception ex)when(ex is ArgumentException or InvalidDataException or JsonException or IOException or InvalidOperationException){rejected=true;}Check(rejected,label);}
var now=DateTimeOffset.UtcNow;var endpoint=Guid.NewGuid().ToString("N");var group=Guid.NewGuid().ToString("N");
var context=new TrustContext("server",group,endpoint,"linux","/fixture/canary",["read"],now,new(Executable:"/fixture/reader",Sha256:new string('a',64),Verified:true));
var cache=new TrustPolicyCache(root,endpoint,"https://fixture.invalid");cache.Load();
Check(cache.Evaluate(context,now) is {Mode:"pending",Decision:{SuppressPopup:false,SuppressResponse:true,RetainEvidence:true}},"no authenticated policy preserves alerts and pauses automatic response");
var rule=new TrustRule(Guid.NewGuid().ToString("N"),"organization","server","process",["read"],"informational",now.AddMinutes(-1),now.AddDays(1)){Enabled=true,Executable="/fixture/reader",Sha256=new string('a',64)};
var policy=new TrustPolicy(1,"enforce",[rule],[],"fixture-admin",now);
var assignment=new AssignedTrustPolicy(endpoint,group,policy,policy.Digest(),now,now.AddHours(24));
cache.Save(assignment,now);Check(cache.Evaluate(context,now) is {Mode:"enforce",Decision:{Severity:"informational",SuppressPopup:false,SuppressResponse:false}},"allowlist lowers severity without suppressing popup or response");
var reopened=new TrustPolicyCache(root,endpoint,"https://fixture.invalid/");reopened.Load();Check(reopened.Current?.Digest==assignment.Digest,"reopen preserves exact server/enrollment-bound policy");
Check(reopened.Evaluate(context,now.AddHours(25)) is {Mode:"pending",Decision:{SuppressPopup:false,SuppressResponse:true}},"offline expiry returns to alert-only, not legacy exemptions");
Check(reopened.Evaluate(context with{Group=null},now).Mode=="pending","changed group requires authenticated reassignment");
Check(reopened.Evaluate(context with{Host=Guid.NewGuid().ToString("N")},now).Mode=="pending","another endpoint cannot evaluate this assignment");
Check(reopened.Evaluate(context with{ProtectedEvent=true},now).Decision.Disposition=="normal","health/security events remain unsuppressed");
Check(reopened.Evaluate(context with{Actions=["delete"]},now).Decision.Disposition=="normal","deletion remains unsuppressed");
Check(reopened.Evaluate(context with{Actor=new()},now).Decision.Disposition=="normal","missing actor evidence cannot earn trust");
Reject(()=>new TrustPolicyCache(root,Guid.NewGuid().ToString("N"),"https://fixture.invalid").Load(),"another enrollment rejected");
Reject(()=>new TrustPolicyCache(root,endpoint,"https://different.invalid").Load(),"another management origin rejected");
Reject(()=>cache.Save(assignment with{Digest=new string('0',64)},now),"digest mismatch rejected");
var older=TrustPolicy.Default;
Reject(()=>cache.Save(assignment with{Policy=older,Digest=older.Digest()},now),"revision downgrade rejected");
var conflict=policy with{Rules=[]};Reject(()=>cache.Save(assignment with{Policy=conflict,Digest=conflict.Digest()},now),"same revision different content rejected");
Reject(()=>cache.Save(assignment with{IssuedUtc=now.AddMinutes(-1),ExpiresUtc=now.AddHours(23)},now),"older assignment replay rejected");
Reject(()=>cache.Save(assignment with{IssuedUtc=now.AddMinutes(2),ExpiresUtc=now.AddHours(24)},now),"future assignment rejected");
Reject(()=>cache.Save(assignment,now.AddHours(25)),"expired assignment rejected");
Check(cache.Current?.Digest==policy.Digest(),"all invalid saves preserve current state");
var external=cache.Current!;external.Policy.Rules[0]=rule with{Disposition="popup-and-response"};Check(cache.Evaluate(context,now).Decision.SuppressResponse==false,"callers cannot mutate cached rules through snapshot");
var renewal=assignment with{IssuedUtc=now.AddMinutes(1),ExpiresUtc=now.AddHours(24).AddMinutes(1)};cache.Save(renewal,now.AddMinutes(1));Check(cache.Current!.ExpiresUtc==renewal.ExpiresUtc,"same revision renews bounded offline validity");
var reset=new TrustPolicy(2,"legacy",[],[],"fixture-admin",now.AddMinutes(2));cache.Save(renewal with{Policy=reset,Digest=reset.Digest(),IssuedUtc=now.AddMinutes(2)},now.AddMinutes(2));Check(cache.Evaluate(context,now.AddMinutes(2)).Mode=="legacy","only a newer authenticated revision restores explicit legacy mode");
var wire=new AgentEvent(Guid.NewGuid().ToString("N"),now,"Content read (copy possible)","/fixture/canary","synthetic","/fixture/reader",99,"Linux fanotify");
var trusted=TrustEventEvaluation.Evaluate(reopened,endpoint,group,"linux",wire,context.Actor,now);Check(trusted.IsValid()&&trusted.Result.Decision.Severity=="informational"&&!trusted.Result.Decision.SuppressPopup,"event decision retains scoped rule evidence");
var spool=new EventSpool(root,endpoint);spool.Enqueue(wire with{Trust=trusted});var batch=spool.Peek();
Reject(()=>spool.Acknowledge(batch,new(1,0)),"old server receipt cannot discard new trust evidence");
Check(spool.Status.Pending==1,"unacknowledged trust event retained");
var forged=new EventBatch([batch.Events[0] with{Trust=trusted with{Result=trusted.Result with{Decision=trusted.Result.Decision with{Reason="changed"}}}}]);
Reject(()=>spool.Acknowledge(forged,new(1,0){TrustVersion=1,WhitelistVersion=1}),"changed nested decision cannot acknowledge queue prefix");
spool.Acknowledge(batch,new(1,0){TrustVersion=1,WhitelistVersion=1});Check(spool.Status.Pending==0,"deserialized nested-rule arrays acknowledge exact durable payload");
Check(!TrustEventEvaluation.LinuxActor(endpoint,wire with{Attribution=new(){Provider="fanotify + procfs",UserId=1000,ExecutableSha256=new string('a',64)}}).Verified,"later procfs observations cannot earn event-time trust");
var audit=wire with{Source="Linux Audit",Attribution=new(){Provider="Linux Audit",UserId=1000,CompleteRecordSet=true,EventTimeCredentials=true}};
Check(TrustEventEvaluation.LinuxActor(endpoint,audit) is {Verified:true,AccountId:"1000",Authority:var authority,Sha256:null}&&authority==endpoint,"complete audit UID is endpoint-scoped without fabricated executable hash");
Check(!TrustEventEvaluation.LinuxActor(endpoint,audit with{Attribution=audit.Attribution! with{CompleteRecordSet=false}}).Verified,"incomplete audit evidence cannot match account exception");
var many=Enumerable.Range(0,1000).Select(_=>rule with{Id=Guid.NewGuid().ToString("N")}).ToArray();var bounded=TrustEvaluation.Evaluate(many,context,now);Check(bounded.MatchedRules.Length==64&&bounded.MatchedRuleCount==1000,"large match sets are bounded without hiding total rule count");
var file=Path.Combine(root,"managed-trust.json");File.WriteAllText(file,"invalid fixture cache");var damaged=new TrustPolicyCache(root,endpoint,"https://fixture.invalid");Reject(damaged.Load,"corrupt state rejected");Reject(()=>damaged.Save(assignment,now),"corrupt evidence not silently overwritten");Check(damaged.Evaluate(context,now).Mode=="pending"&&File.ReadAllText(file)=="invalid fixture cache","damaged state remains alert-only with original evidence");
File.WriteAllLines(Path.Combine(root,"results.txt"),checks);Console.WriteLine(root);Console.WriteLine("Pure/local durable cache only; native service, transport and UI acceptance not inferred.");
